use std::sync::Arc;
use axum::{extract::State, http::StatusCode, response::{IntoResponse, Response}, Json};
use serde_json::{json, Value};
use sqlx::Row;
use uuid::Uuid;
use crate::{security::require_proxy_context,state::AppState};
use super::{queries,responses::{api_error,unavailable},types::{ApiCreateTransactionData,ApiCreateTransactionPayload,ApiCreateTransactionResponse}};

pub async fn create_transaction(headers:axum::http::HeaderMap,State(state):State<Arc<AppState>>,Json(payload):Json<ApiCreateTransactionPayload>)->Response{
 if let Err(r)=require_proxy_context(&headers,&state){return r;}
 let value=|name:&str|headers.get(name).and_then(|v|v.to_str().ok());
 let (Some(member),Some(key),Some(sig))=(value("x-open-api-member_id"),value("x-open-api-api_key"),value("x-open-api-signature"))else{return api_error(StatusCode::UNAUTHORIZED,"Invalid API key")};
 let ref_header=value("x-open-api-ref_id");let principal=match queries::authenticate(&state.pg_pool,member,key,sig,ref_header).await{Ok(Some(v))=>v,Ok(None)=>return api_error(StatusCode::UNAUTHORIZED,"Invalid API key"),Err(_)=>return unavailable()};
 let code=payload.product_code.as_deref().unwrap_or_default().trim();let target=payload.target.as_deref().unwrap_or_default().trim();let server=payload.server_id.as_deref().unwrap_or_default().trim();let customer_ref=payload.ref_id.as_deref().map(str::trim).filter(|v|!v.is_empty());
 if code.is_empty()||target.is_empty(){return api_error(StatusCode::BAD_REQUEST,"product_code and target are required")};
 if customer_ref!=ref_header.filter(|v|!v.is_empty()){return api_error(StatusCode::UNAUTHORIZED,"Invalid signature")};
 let digest=format!("{:x}",md5::compute(format!("{code}\0{target}\0{server}").as_bytes()));
 let product=match sqlx::query("SELECT p.id,p.name,p.price_basic,p.price_gold,p.price_platinum,p.vendor_name,p.vendor_sku,c.status category_status,c.is_active category_active,o.status operator_status,t.status type_status FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN operators o ON o.id=p.operator_id LEFT JOIN product_types t ON t.id=p.product_type_id WHERE p.code=$1 AND p.status=true").bind(code).fetch_optional(&state.pg_pool).await{Ok(Some(v))=>v,Ok(None)=>return api_error(StatusCode::NOT_FOUND,"Product not found or unavailable"),Err(_)=>return unavailable()};
 if product.get::<Option<bool>,_>("category_status")==Some(false)||product.get::<Option<bool>,_>("category_active")==Some(false)||product.get::<Option<bool>,_>("operator_status")==Some(false)||product.get::<Option<bool>,_>("type_status")==Some(false){return (StatusCode::BAD_REQUEST,Json(json!({"success":false,"message":"Product unavailable: Kategori/operator/jenis produk nonaktif"}))).into_response()}
 let price:i64=match principal.level.as_str(){"gold"=>product.get("price_gold"),"platinum"=>product.get("price_platinum"),_=>product.get("price_basic")};if price<=0{return api_error(StatusCode::BAD_REQUEST,"Product not found or unavailable")};
 let product_id:Uuid=product.get("id");let product_name:String=product.get("name");let vendor_name:String=product.get("vendor_name");let vendor_sku:String=product.get("vendor_sku");
 let mut tx=match state.pg_pool.begin().await{Ok(v)=>v,Err(_)=>return unavailable()};
 let user=match sqlx::query("SELECT balance FROM users WHERE id=$1 AND role='member' AND active=true FOR UPDATE").bind(principal.id).fetch_optional(&mut *tx).await{Ok(Some(v))=>v,Ok(None)=>return api_error(StatusCode::NOT_FOUND,"User not found"),Err(_)=>return unavailable()};let balance:i64=user.get("balance");
 if let Some(reference)=customer_ref{match sqlx::query("SELECT digest,response,response_status FROM financial_requests WHERE actor=$1 AND operation='open-api-order' AND key=$2 FOR UPDATE").bind(principal.id.to_string()).bind(reference).fetch_optional(&mut *tx).await{Ok(Some(row))=>{if row.get::<String,_>("digest")!=digest{return duplicate_ref_conflict()};if let Some(response)=row.get::<Option<Value>,_>("response"){return (StatusCode::from_u16(row.get::<Option<i32>,_>("response_status").unwrap_or(200) as u16).unwrap_or(StatusCode::OK),Json(response)).into_response()}return (StatusCode::CONFLICT,Json(json!({"success":false,"message":"Transaction is being processed"}))).into_response()},Ok(None)=>{},Err(_)=>return unavailable()}}
 if balance<price{return (StatusCode::BAD_REQUEST,Json(json!({"success":false,"message":"Insufficient balance","data":{"required":price,"current_balance":balance}}))).into_response()};let next=balance-price;let id=Uuid::new_v4();let reference=Uuid::new_v4().to_string();let snapshot=json!({"product":{"code":code,"name":product_name,"vendorName":vendor_name,"vendorSku":vendor_sku},"target":target,"serverId":server,"source":"api"});
 let created=match sqlx::query("INSERT INTO financial_transactions(id,reference_id,user_id,product_id,kind,amount,status,partner_ref,snapshot,target,server_id,source,base_amount,provider_reference) VALUES($1,$2,$3,$4,'member',$5,'pending',$6,$7,$8,$9,'api',$5,$2) RETURNING created_at").bind(id).bind(&reference).bind(principal.id).bind(product_id).bind(price).bind(customer_ref).bind(&snapshot).bind(target).bind(server).fetch_one(&mut *tx).await{Ok(row)=>row.get::<chrono::DateTime<chrono::Utc>,_>("created_at"),Err(e)if e.as_database_error().is_some_and(|d|d.is_unique_violation())=>return duplicate_ref(&state,principal.id,customer_ref).await,Err(_)=>return unavailable()};
 if sqlx::query("UPDATE users SET balance=$2,updated_at=now() WHERE id=$1").bind(principal.id).bind(next).execute(&mut *tx).await.is_err()||sqlx::query("INSERT INTO ledger_entries(user_id,source,kind,direction,amount,balance_after) VALUES($1,$2,'debit',-1,$3,$4)").bind(principal.id).bind(format!("open-api:{id}")).bind(price).bind(next).execute(&mut *tx).await.is_err(){return unavailable()}
 let job=json!({"referenceId":reference,"productCode":code,"sku":vendor_sku,"target":target,"serverId":server,"amount":price,"source":"api"});
 if sqlx::query("INSERT INTO financial_provider_jobs(reference_id,snapshot) VALUES($1,$2)").bind(&reference).bind(&job).execute(&mut *tx).await.is_err()||sqlx::query("INSERT INTO provider_outbox(ref_id,payload,state) VALUES($1,$2,'pending')").bind(&reference).bind(&job).execute(&mut *tx).await.is_err(){return unavailable()}
 let response=ApiCreateTransactionResponse{success:true,message:"Transaction created",data:ApiCreateTransactionData{trx_id:json!(id.to_string()),ref_id:customer_ref.map(str::to_owned),product_code:code.to_owned(),product_name,target:target.to_owned(),price,status:"pending".to_owned(),sn:None,balance:next,created_at:created.to_rfc3339()}};
 if let Some(reference)=customer_ref{let body=match serde_json::to_value(&response){Ok(v)=>v,Err(_)=>return unavailable()};if sqlx::query("INSERT INTO financial_requests(actor,operation,key,digest,response,response_status) VALUES($1,'open-api-order',$2,$3,$4,200)").bind(principal.id.to_string()).bind(reference).bind(digest).bind(body).execute(&mut *tx).await.is_err(){return unavailable()}}
 if tx.commit().await.is_err(){return unavailable()};Json(response).into_response()
}
async fn duplicate_ref(state:&AppState,user:Uuid,ref_id:Option<&str>)->Response{if let Some(r)=ref_id{if let Ok(Some(row))=sqlx::query("SELECT id,status FROM financial_transactions WHERE user_id=$1 AND partner_ref=$2").bind(user).bind(r).fetch_optional(&state.pg_pool).await{return (StatusCode::BAD_REQUEST,Json(json!({"success":false,"message":"Duplicate ref_id","data":{"existing_trx_id":row.get::<Uuid,_>("id").to_string(),"status":row.get::<String,_>("status")}}))).into_response()}}duplicate_ref_conflict()}
fn duplicate_ref_conflict()->Response{(StatusCode::BAD_REQUEST,Json(json!({"success":false,"message":"Duplicate ref_id"}))).into_response()}
